#!/usr/bin/env node
import fs from"node:fs";import path from"node:path";import{pathToFileURL}from"node:url";const IGNORED_DIRS=new Set([".git","node_modules","dist","coverage"]);export function collectHtmlFiles(e,t=[]){for(const i of fs.readdirSync(e,{withFileTypes:!0})){if(IGNORED_DIRS.has(i.name))continue;const s=path.join(e,i.name);i.isDirectory()?collectHtmlFiles(s,t):i.name.endsWith(".html")&&t.push(s)}return t}function stripNonMarkup(e){const t=e=>e.replace(/[^\n]/g," ");return e.replace(/<!--[\s\S]*?-->/g,t).replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi,t).replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi,t)}function lineOf(e,t){return e.slice(0,t).split("\n").length}export const RULES=[{id:"img-alt",describe:'every <img> needs an alt attribute (use alt="" if decorative)',run(e){const t=[];for(const i of e.matchAll(/<img\b[^>]*>/gi))/\salt\s*=/i.test(i[0])||t.push({line:lineOf(e,i.index),detail:i[0].slice(0,80)});return t}},{id:"html-lang",describe:"<html> needs a lang attribute so screen readers pick the right voice",run:e=>/<html\b[^>]*\slang\s*=\s*["'][^"']+["']/i.test(e)?[]:[{line:lineOf(e,Math.max(0,e.search(/<html/i))),detail:"<html> has no lang"}]},{id:"page-title",describe:"<title> must be present and non-empty",run(e){const t=e.match(/<title\b[^>]*>([\s\S]*?)<\/title>/i);return t&&t[1].trim()?[]:[{line:t?lineOf(e,t.index):1,detail:"missing or empty <title>"}]}},{id:"duplicate-id",describe:"id attributes must be unique (aria references resolve to the first match)",run(e){const t=[],i=new Map;for(const s of e.matchAll(/\sid\s*=\s*["']([^"']+)["']/gi)){const n=s[1];i.has(n)?t.push({line:lineOf(e,s.index),detail:`id "${n}" also used on line ${i.get(n)}`}):i.set(n,lineOf(e,s.index))}return t}},{id:"control-name",describe:"buttons and links need an accessible name (text, aria-label, or title)",run(e){const t=[],i=/<(button|a)\b([^>]*)>([\s\S]*?)<\/\1>/gi;for(const s of e.matchAll(i)){const[i,n,l,o]=s;/\saria-label\s*=\s*["']\s*\S/i.test(l)||(/\saria-labelledby\s*=/i.test(l)||/\stitle\s*=\s*["']\s*\S/i.test(l)||/\saria-hidden\s*=\s*["']true["']/i.test(l)||("a"!==n.toLowerCase()||/\shref\s*=/i.test(l))&&(/<img\b[^>]*\salt\s*=\s*["']\s*\S/i.test(o)||o.replace(/<[^>]*>/g,"").trim()||t.push({line:lineOf(e,s.index),detail:i.slice(0,80).replace(/\s+/g," ")})))}return t}}];export function auditAccessibility(e=collectHtmlFiles(".")){const t=[];for(const i of e){const e=stripNonMarkup(fs.readFileSync(i,"utf8"));for(const s of RULES)for(const n of s.run(e))t.push({file:i,line:n.line,rule:s.id,detail:n.detail,describe:s.describe})}return{totalScanned:e.length,violations:t}}const isMain=process.argv[1]&&import.meta.url===pathToFileURL(process.argv[1]).href;if(isMain){const e=process.argv.slice(2).filter(e=>e.endsWith(".html")),t=e.length?e:collectHtmlFiles("."),i=t.filter(e=>!fs.existsSync(e));i.length&&(console.error(`File(s) not found: ${i.join(", ")}`),process.exit(1));const{totalScanned:s,violations:n}=auditAccessibility(t);for(const l of n)console.error(`${l.file}:${l.line}  [${l.rule}] ${l.detail}`),console.error(`    ${l.describe}`);console.log(`\nAccessibility check: scanned ${s} page(s), found ${n.length} violation(s).`),n.length>0&&(console.error("\nFix the violations above, or justify an exception in the PR description."),process.exit(1))}